"using System.Collections;
using UnityEngine;

public enum RegionMode { Cebu, Ilocos, BossBattle }

/// <summary>
/// Orchestrates the full region experience while re‑using existing managers.
/// Flow: Cutscene → Lesson UI → STT → Minigame → Quest → Crystal trial → Journal.
/// </summary>
public class RegionFlowController : MonoBehaviour
{
    [Header("Managers")]
    [SerializeField] private LessonManager lessonManager;
    [SerializeField] private MinigameManager minigameManager;
    [SerializeField] private JournalManager journalManager;
    [SerializeField] private ObjectiveManager objectiveManager;

    // Reference to the CutscenePlayer (assign in inspector, can be empty)
    [SerializeField] private CutscenePlayer cutscenePlayer;

    private Coroutine _flowRoutine;

    /// <summary>Called by the guide NPC after its final dialogue node.</summary>
    public void StartRegion(RegionMode mode)
